-- Features per (dataset, split, unit_id, cycle). All rolling windows are CAUSAL (current + previous cycles only),
-- so a feature at cycle t never uses information from cycles after t.
--   *_raw      raw sensor value (no regime correction)       *_n   per-(dataset,condition) z-score (train-split stats)
--   *_rm10/30  rolling mean of *_n                          *_rs10  rolling std of *_n   (window = 10 cycles)
DROP TABLE IF EXISTS features;
CREATE TABLE features AS
WITH m AS (
  SELECT n.dataset, n.condition_id,
  max(CASE WHEN n.sensor='s2' THEN n.mu END) AS s2_mu, max(CASE WHEN n.sensor='s2' THEN n.sd END) AS s2_sd,
  max(CASE WHEN n.sensor='s3' THEN n.mu END) AS s3_mu, max(CASE WHEN n.sensor='s3' THEN n.sd END) AS s3_sd,
  max(CASE WHEN n.sensor='s4' THEN n.mu END) AS s4_mu, max(CASE WHEN n.sensor='s4' THEN n.sd END) AS s4_sd,
  max(CASE WHEN n.sensor='s7' THEN n.mu END) AS s7_mu, max(CASE WHEN n.sensor='s7' THEN n.sd END) AS s7_sd,
  max(CASE WHEN n.sensor='s8' THEN n.mu END) AS s8_mu, max(CASE WHEN n.sensor='s8' THEN n.sd END) AS s8_sd,
  max(CASE WHEN n.sensor='s9' THEN n.mu END) AS s9_mu, max(CASE WHEN n.sensor='s9' THEN n.sd END) AS s9_sd,
  max(CASE WHEN n.sensor='s11' THEN n.mu END) AS s11_mu, max(CASE WHEN n.sensor='s11' THEN n.sd END) AS s11_sd,
  max(CASE WHEN n.sensor='s12' THEN n.mu END) AS s12_mu, max(CASE WHEN n.sensor='s12' THEN n.sd END) AS s12_sd,
  max(CASE WHEN n.sensor='s13' THEN n.mu END) AS s13_mu, max(CASE WHEN n.sensor='s13' THEN n.sd END) AS s13_sd,
  max(CASE WHEN n.sensor='s15' THEN n.mu END) AS s15_mu, max(CASE WHEN n.sensor='s15' THEN n.sd END) AS s15_sd,
  max(CASE WHEN n.sensor='s17' THEN n.mu END) AS s17_mu, max(CASE WHEN n.sensor='s17' THEN n.sd END) AS s17_sd,
  max(CASE WHEN n.sensor='s20' THEN n.mu END) AS s20_mu, max(CASE WHEN n.sensor='s20' THEN n.sd END) AS s20_sd,
  max(CASE WHEN n.sensor='s21' THEN n.mu END) AS s21_mu, max(CASE WHEN n.sensor='s21' THEN n.sd END) AS s21_sd
  FROM norm_stats n GROUP BY n.dataset, n.condition_id
), base AS (
  SELECT r.dataset, r.split, r.unit_id, r.cycle, o.condition_id,
         r.op_setting_1, r.op_setting_2, r.op_setting_3,
         r.s2 AS s2_raw, r.s3 AS s3_raw, r.s4 AS s4_raw, r.s7 AS s7_raw, r.s8 AS s8_raw, r.s9 AS s9_raw, r.s11 AS s11_raw, r.s12 AS s12_raw, r.s13 AS s13_raw, r.s15 AS s15_raw, r.s17 AS s17_raw, r.s20 AS s20_raw, r.s21 AS s21_raw,
         (r.s2 - m.s2_mu) / m.s2_sd AS s2_n, (r.s3 - m.s3_mu) / m.s3_sd AS s3_n, (r.s4 - m.s4_mu) / m.s4_sd AS s4_n, (r.s7 - m.s7_mu) / m.s7_sd AS s7_n, (r.s8 - m.s8_mu) / m.s8_sd AS s8_n, (r.s9 - m.s9_mu) / m.s9_sd AS s9_n, (r.s11 - m.s11_mu) / m.s11_sd AS s11_n, (r.s12 - m.s12_mu) / m.s12_sd AS s12_n, (r.s13 - m.s13_mu) / m.s13_sd AS s13_n, (r.s15 - m.s15_mu) / m.s15_sd AS s15_n, (r.s17 - m.s17_mu) / m.s17_sd AS s17_n, (r.s20 - m.s20_mu) / m.s20_sd AS s20_n, (r.s21 - m.s21_mu) / m.s21_sd AS s21_n
  FROM sensor_readings r
  JOIN op_conditions o USING (dataset, split, unit_id, cycle)
  JOIN m ON m.dataset = r.dataset AND m.condition_id = o.condition_id
)
SELECT dataset, split, unit_id, cycle, condition_id, op_setting_1, op_setting_2, op_setting_3,
  s2_raw,
  avg(s2_raw) OVER w10 AS s2_raw_rm10,
